[1124] = { en = "Wasteland", tier = 4,
  t = "Woestenij",
  d = "Ten westen van Un'Goro Crater, via de noordwestelijke bergkam, ligt een ruige woestenij: Silithus.  Weinigen weten dat daar een oude oorlog werd gevoerd tussen de nachtelfen en een kwaadaardige, vreemde macht.  Het kwaad werd opgesloten, maar nu vermoeden we dat er krachten bezig zijn om deze... onbeschrijflijke verschrikking te wekken.$B$BZoek Layo Starstrike op, een van onze agenten in Silithus. Je vindt hem bij Valor's Rest, de laatste rustplaats voor de gevallenen van de woestenij.  Geef hem deze brief, dan zal hij je ook vertrouwen.",
  o = "Spreek met Layo Starstrike bij de begraafplaats Valor's Rest in Silithus en laat hem Rabine's Letter zien.",
  p = "Dit is een gevaarlijk land om zo onbezorgd te zijn, $c.  Wat brengt je naar de woestenij van Silithus?",
  c = "Rabine heeft je gestuurd?  Nou, voel je hier welkom... voor zover dit troosteloze, verlaten land iemand welkom kan heten.$B$BIk leefde nog niet in de tijd van de grote beproevingen die hier plaatsvonden, maar sommige delen van deze woestijn lijken wel griezelige beelden van dat vergeten verleden.  Met jouw hulp kan de Cenarion Circle misschien definitief een einde maken aan een bedreiging die generaties geleden al had moeten sterven.",
  g = { {"woestenij", "wasteland"}, {"bergkam", "ridge"}, {"ruige", "harsh, rough (ruig)"}, {"gevoerd", "waged (voeren)"}, {"kwaadaardige", "malign, evil (kwaadaardig)"}, {"opgesloten", "sealed, locked up (opsluiten)"}, {"vermoeden", "suspect"}, {"onbeschrijflijke", "unspeakable, indescribable (onbeschrijflijk)"}, {"verschrikking", "horror"}, {"wekken", "to wake, to stir"}, {"rustplaats", "resting place"}, {"onbezorgd", "carefree, casual"}, {"troosteloze", "desolate (troosteloos)"}, {"beproevingen", "tribulations, trials (beproeving)"}, {"griezelige", "eerie (griezelig)"} },
},

[1185] = { en = "Under the Chitin Was...", tier = 4,
  t = "Onder de chitine zat...",
  c = "Hé, jij weer! Nou ja, ik bedoel jij - de jij die $N is! Ja - die jij!$B$BHé, laat me opnieuw beginnen!$B$BDat voorwerp dat je in Silithus hebt gevonden - het was echt een boek. Het was een dagboek, geschreven in een heel oud dialect van wat we nu de Darnassische taal noemen. Het gaat even duren, maar ik ga het heel grondig bekijken. Ik vond dat je moest weten dat wat je hebt gevonden heel waardevol was voor de Circle.$B$BDe holmoeder is helemaal enthousiast en zo!",
  g = { {"chitine", "chitin (insect shell material)"}, {"voorwerp", "object"}, {"dagboek", "journal, diary"}, {"dialect", "dialect"}, {"Darnassische", "Darnassian"}, {"grondig", "thoroughly"}, {"waardevol", "valuable"}, {"holmoeder", "den mother"} },
},

[6845] = { en = "Uncovering Past Secrets", tier = 4,
  t = "Oude geheimen ontrafelen",
  d = "Hoe dan ook, kom binnenkort nog eens bij me langs... tenminste, als je wilt weten wat hierin stond.  Zodra ik ontdek wat het is, en of het echt een boek is, vertel ik je dat graag.$B$BIntussen zou ik even langsgaan bij de holmoeder van dit kleine berenkamp, Rabine.  Hij wil vast weten wat voor gekke streken jij hebt uitgehaald.  Laat de holmoeder nooit wachten, $N... tenzij je met honing overgoten wilt worden.$B$BHet is echt gebeurd, geloof me.",
  o = "Spreek met Rabine Saturna in het dorp Nighthaven, Moonglade.",
  c = "Ah, $N - ik hoopte al dat je langs zou komen. Fijn om te zien dat het goed met je gaat.$b$bIk hoorde dat je terug zou komen uit het veld, en ik wilde je persoonlijk de dank van de Cenarion Circle laten weten voor de hulp die je ons tot nu toe hebt gegeven. Er zijn vast nog meer geheimen in Silithus te ontdekken; wat je bij Umber hebt afgeleverd, zal heel interessant blijken zodra het onthuld is. Neem dit alsjeblieft aan als blijk van onze blijvende waardering voor je hulp.$b$bDank je, vrijgevige $C.",
  g = { {"ontrafelen", "to uncover, to unravel"}, {"tenminste", "at least, that is"}, {"zodra", "as soon as"}, {"intussen", "in the meantime"}, {"holmoeder", "den mother"}, {"streken", "antics, tricks (streek)"}, {"uitgehaald", "pulled, got up to (uithalen)"}, {"overgoten", "doused (overgieten)"}, {"onthuld", "uncovered, revealed (onthullen)"}, {"als blijk van", "as a token of"}, {"waardering", "appreciation"}, {"vrijgevige", "generous (vrijgevig)"} },
},

[5526] = { en = "Shards of the Felvine", tier = 4,
  t = "Scherven van de Felvine",
  d = "Je kennis van Eldre'Thalas - Dire Maul - in Feralas komt nu van pas, $N.  In het oostelijke deel van de verwoeste stad heeft Alzzin the Wildshaper zijn verdorven heerschappij gevestigd.  Ga daar zo snel mogelijk heen en trotseer alle uitdagingen die je te wachten staan.$B$BHet Fruit of Fertility, nu verdorven tot de Felvine, zou dicht bij Alzzin moeten zijn.  Als hij valt, vang dan zoveel van de essentie van de Felvine als je kunt.  Sluit die op in de Reliquary en breng hem naar mij.$B$BVeel geluk, en de snelheid van Cenarion.",
  o = "Vind de Felvine in Dire Maul en bemachtig er een scherf van.  Waarschijnlijk lukt dat alleen als Alzzin the Wildshaper sterft.  Gebruik de Reliquary of Purity om de scherf er veilig in op te sluiten, en breng hem terug naar Rabine Saturna in Nighthaven, Moonglade.",
  p = "Met de Sealed Reliquary of Purity in ons bezit kunnen we niet alleen een verdorven bedreiging uit de wereld verwijderen, maar die ook bestuderen onder ons zorgvuldige toezicht. Misschien kunnen we zelfs nieuwe manieren bedenken om de smet van verdorvenheid te bestrijden die Azeroth altijd bedreigt.$b$bIk weet dat Milli het niet anders had gewild...",
  c = "Het is volbracht, dappere $C, en daarmee staat de Cenarion Circle bij je in de schuld. Hoewel de oorlog nog lang niet voorbij is, is er een grote slag gewonnen tegen wie onze ondergang willen brengen.$b$bNeem dit alsjeblieft aan als blijk van onze blijvende dankbaarheid. Weet dat je hier welkom bent als held van de Cenarion Circle, vanwege je grote daad, $N. Dank je.",
  g = { {"scherven", "shards (scherf)"}, {"komt van pas", "comes into play, comes in handy (van pas komen)"}, {"verwoeste", "ruined (verwoest)"}, {"verdorven", "corrupt(ed)"}, {"heerschappij", "dominion, rule"}, {"trotseer", "brave, defy (trotseren)"}, {"essentie", "essence"}, {"bemachtig", "acquire (bemachtigen)"}, {"bezit", "possession"}, {"toezicht", "watch, supervision"}, {"smet", "taint, stain"}, {"verdorvenheid", "corruption"}, {"volbracht", "done, accomplished (volbrengen)"}, {"in de schuld", "in debt"}, {"ondergang", "doom, downfall"} },
},

[5527] = { en = "A Reliquary of Purity", tier = 4,
  t = "Een Reliquary of Purity",
  d = "De eerste stap is een houder vinden die een uiterst verderfelijke stof kan bevatten, zonder dat degene die hem vasthoudt er nadelige gevolgen van ondervindt.  Ik ken maar één soort voorwerp dat iets zo walgelijks als de Felvine zou kunnen bevatten: een Reliquary of Purity.$B$BDiep in de woestenij van Silithus liggen de resten van het nachtelfendorp Southwind.  Ik weet dat er vele, vele jaren geleden een was.  Als we willen slagen, moet je die ruïnes uitkammen in de hoop hem terug te vinden.",
  o = "Reis naar Silithus en zoek naar een Reliquary of Purity in de ruïnes van Southwind Village.  Als je hem vindt, breng hem dan terug naar Rabine Saturna in Nighthaven, Moonglade.",
  p = "Een Reliquary of Purity is op zich al een artefact.  Er zijn er maar weinig gemaakt, en men dacht dat bijna allemaal in de loop van de tijd verloren waren gegaan.$B$BIk geef toe dat ik al een tijdje van die in Southwind afweet.  Eerlijk gezegd, met de groeiende onrust in Silithus wilde ik onze geheimen precies dat houden: geheim.  Rondneuzen zou alleen de argwaan van onze vijanden wekken.$B$BHelaas is de tijd van stilzitten voorbij, vooral met de situatie in Eldre'Thalas. ",
  c = "Je bent inderdaad zo vindingrijk als velen zeggen. De Cenarion Circle mag zich gelukkig prijzen dat jij voor ons werkt.$b$bNu de Reliquary weer in onze handen is, ben ik gerust. Ik vraag je met een geruster gevoel om niet alleen een kwaadaardige demon te verslaan, maar daarbij ook een gevaarlijk voorwerp mee terug te brengen...",
  g = { {"houder", "container"}, {"verderfelijke", "corrupting, pernicious (verderfelijk)"}, {"bevatten", "to contain, to hold"}, {"nadelige gevolgen", "ill effects"}, {"ondervindt", "experiences, suffers (ondervinden)"}, {"walgelijks", "vile, disgusting (walgelijk)"}, {"resten", "remnants (rest)"}, {"uitkammen", "to scour, to comb"}, {"op zich", "in itself"}, {"onrust", "turmoil, unrest"}, {"rondneuzen", "poking around"}, {"argwaan", "suspicion"}, {"stilzitten", "sitting still, complacency"}, {"vindingrijk", "resourceful"}, {"zich gelukkig prijzen", "to count oneself lucky"} },
},

[8447] = { en = "Waking Legends", tier = 4,
  t = "Ontwakende legenden",
  d = "Het water van Lake Elune'ara zou de nachtmerries die dit voorwerp omhullen moeten oplossen. Geef me even de tijd om de reiniging uit te voeren, $N.",
