[8735] = { en = "The Nightmare's Corruption", tier = 4,
  t = "De verdorvenheid van de Nightmare",
  d = "Je moet naar de vier droomportalen van Azeroth reizen. Uit elk ervan moet je een fragment van de verdorvenheid van de Nightmare halen. Het drakenvolk dat in die gebieden woont, draagt zulke fragmenten bij zich. Kom bij me terug als je deze fragmenten hebt verzameld.",
  o = "Reis naar de vier Emerald Dream-portalen in Azeroth en verzamel bij elk een Fragment of the Nightmare's Corruption. Keer terug naar Keeper Remulos in de Moonglade als je deze taak hebt voltooid.$b",
  p = "<Remulos is diep in gedachten verzonken.>",
  c = "Ben je er klaar voor? Is de wereld klaar voor wat we op het punt staan op te roepen? Ik weet het niet... Ik ben door mijn plicht aan Malfurion gebonden. Plicht en eer...",
  g = { {"verdorvenheid", "corruption"}, {"droomportalen", "dream portals (droomportaal)"}, {"drakenvolk", "dragonkin"}, {"gebieden", "areas (gebied)"}, {"bij zich", "on them, with them"}, {"in gedachten verzonken", "lost in thought"}, {"op het punt staan", "to be about to"}, {"op te roepen", "to invoke, to summon (oproepen)"}, {"plicht", "duty"}, {"gebonden", "bound (binden)"}, {"eer", "honor"} },
},

[8736] = { en = "The Nightmare Manifests", tier = 4,
  t = "De Nightmare openbaart zich",
  d = "We moeten ons inhouden tegenover Eranikus. We moeten hem verlossen, niet vernietigen.$B$BTyrande is al onderweg om ons bij deze taak te helpen. We moeten de klappen van de draak doorstaan en Nighthaven redden van de zekere ondergang.$B$BWees op je hoede! Jij en je bondgenoten zijn onze enige hoop.$b",
  o = "Verdedig Nighthaven tegen Eranikus. Laat Keeper Remulos niet sterven. Dood Eranikus niet. Verdedig jezelf. Wacht op Tyrande.$b",
  c = "Hij is verlost, $n. Hij keert nu terug naar de Droom om recht te zetten wat hij alleen verkeerd heeft gedaan. Eranikus zal een machtige bondgenoot zijn voor Malfurion en mijn vader.$b$bDeze wapens zijn voor jou, $n; ik heb ze van Ysera zelf gekregen. Je doet er goed aan ze te gebruiken in je gevechten tegen de Qiraji.",
  e = "De verlossing van Eranikus",
  g = { {"openbaart zich", "manifests, reveals itself (zich openbaren)"}, {"ons inhouden", "use restraint (zich inhouden)"}, {"verlossen", "to redeem, to save"}, {"vernietigen", "to destroy"}, {"klappen", "blows (klap)"}, {"doorstaan", "to weather, to endure"}, {"zekere ondergang", "certain destruction"}, {"op je hoede", "on guard"}, {"bondgenoten", "allies (bondgenoot)"}, {"recht te zetten", "to right, to put right (rechtzetten)"}, {"machtige", "powerful (machtig)"}, {"verlossing", "redemption"} },
