[8809] = { en = "Extraordinary Materials", tier = 4,
  t = "Buitengewone materialen",
  d = "Vargus, de smid van Cenarion Hold, heeft om betoverde materialen gevraagd.  Hij wil ze gebruiken om krachtige wapens voor onze troepen te smeden.  Haal ze en breng ze direct naar Vargus, zodat de troepen van Cenarion Hold goed uitgerust blijven.",
  o = "Breng 2 Enchanted Thorium Bars en 2 Enchanted Leather naar Vargus in Cenarion Hold in Silithus.  Je moet ook Logistics Task Briefing IX meebrengen om deze quest te voltooien.",
  g = { {"buitengewone", "extraordinary (buitengewoon)"}, {"smid", "blacksmith"}, {"betoverde", "enchanted (betoveren)"}, {"krachtige", "powerful (krachtig)"}, {"troepen", "troops, forces (troep)"}, {"smeden", "to forge, to craft (metal)"}, {"uitgerust", "equipped (uitrusten)"} },
},

[8810] = { en = "Bandages for the Field", tier = 4,
  t = "Verband voor het front",
  d = "Onze voorraad verband op het slagveld raakt gevaarlijk laag, door de verliezen die we onlangs hebben geleden.  Haal een partij EHBO-spullen en lever die af bij Windcaller Proudhorn in Cenarion Hold.",
  o = "Breng 30 Heavy Runecloth Bandages, 30 Heavy Silk Bandages en 30 Heavy Mageweave Bandages naar Windcaller Proudhorn in Cenarion Hold in Silithus.  Je moet ook Logistics Task Briefing X meebrengen om deze quest te voltooien.",
  g = { {"verband", "bandages"}, {"voorraad", "supply, stock"}, {"slagveld", "battlefield"}, {"raakt gevaarlijk laag", "is running dangerously low (raken)"}, {"verliezen", "losses, casualties (verlies)"}, {"geleden", "suffered (lijden)"}, {"EHBO-spullen", "first-aid supplies"}, {"partij", "batch, lot"} },
},

[8829] = { en = "The Ultimate Deception", tier = 4,
  t = "Het ultieme bedrog",
  d = "De Twilight's Hammer werkt via ontelbare lagen van geheimhouding en bedrog.  Hun daden worden in onze wereld uitgevoerd, maar ze worden gepland op een plek die we nog niet hebben kunnen bereiken.$B$BWe denken nu dat de stenen waarmee de Twilight's Hammer hun meerderen oproept, reizen in twee richtingen mogelijk maken.  Om ze op die manier te proberen te gebruiken, moeten we tot in het kleinste detail het gewaad van een Twilight-gezant namaken.$B$BVerzamel de benodigde materialen en breng ze naar Aurel Goldleaf, $N.  ",
  o = "Breng een Skin of Shadow, 3 Frayed Abomination Stitchings en 1 Twilight Cultist Robe naar Aurel Goldleaf in Cenarion Hold in Silithus.  Je moet ook Logistics Task Briefing XI meebrengen om deze quest te voltooien.$b",
  g = { {"ultieme", "ultimate (ultiem)"}, {"bedrog", "deception, deceit"}, {"ontelbare", "countless, innumerable (ontelbaar)"}, {"lagen", "layers (laag)"}, {"geheimhouding", "secrecy"}, {"daden", "deeds, actions (daad)"}, {"uitgevoerd", "carried out (uitvoeren)"}, {"meerderen", "superiors (meerdere)"}, {"oproept", "summons (oproepen)"}, {"tot in het kleinste detail", "down to the last detail"}, {"gewaad", "robe"}, {"gezant", "emissary, envoy"}, {"namaken", "to replicate, to copy"}, {"benodigde", "necessary, required"} },
},

[8857] = { en = "Secrets of the Colossus - Ashi", tier = 4,
  t = "Geheimen van de Colossus - Ashi",
  d = "Ik zoek doorgewinterde avonturiers die bereid en in staat zijn om een vers monster van het omhulsel van de gevallen Colossus of Ashi naar Oglethorpe in Booty Bay te brengen. Nee, nee, ik wil echt niet dat je ook maar in de buurt van het lijk van dat ding komt. Neem gewoon een van mijn monsters mee en schiet een beetje op. Als ze verrot zijn, heeft hij er niets aan!",
  o = "Breng de Colossus of Ashi's Husk naar Oglethorpe Obnoticus in Booty Bay.$b",
  p = "Ja? Wat heb je daar?",
  c = "O, de kippen die ik van dit wonderlijke omhulsel ga maken! Goed gedaan, mijn $gjongen:meid;!",
  g = { {"doorgewinterde", "battle-hardened, seasoned (doorgewinterd)"}, {"bereid", "willing"}, {"in staat", "able, capable"}, {"monster", "sample (here: not 'monster')"}, {"omhulsel", "husk, shell"}, {"gevallen", "fallen"}, {"lijk", "corpse"}, {"schiet een beetje op", "make it snappy (opschieten)"}, {"verrot", "rotten"}, {"wonderlijke", "wondrous (wonderlijk)"} },
},

[8858] = { en = "Secrets of the Colossus - Regal", tier = 4,
  t = "Geheimen van de Colossus - Regal",
  d = "Er is niks wat ik liever zou doen dan dit insectenomhulsel in die dikke kop van Oilfist te proppen... Alleen zit ik hier vast, monsters te verzamelen van die uit de kluiten gewassen kakkerlak. Zo groot als dat ding is, zit ik hier tot in de kleine uurtjes.$B$BBreng dit monster voor me naar Oilfist, en snel een beetje, $c. Hij betaalt VEEL!$B$BJawel, Thorium Point - dat ligt in de Searing Gorge.",
  o = "Breng de Colossus of Regal's Husk naar Overseer Oilfist in Searing Gorge.$b",
  p = "Hmmm...",
  c = "Uitstekend. Van deze chitine kunnen we vast ongelooflijk sterk pantser maken. Hier zijn de rijkdommen die je beloofd zijn.",
  g = { {"insectenomhulsel", "bug husk"}, {"proppen", "to stuff, to cram"}, {"zit vast", "am stuck (vastzitten)"}, {"monsters", "samples (monster)"}, {"uit de kluiten gewassen", "overgrown, oversized"}, {"kakkerlak", "cockroach"}, {"tot in de kleine uurtjes", "until the wee hours"}, {"chitine", "chitin (insect shell material)"}, {"pantser", "armor"}, {"rijkdommen", "riches (rijkdom)"}, {"beloofd", "promised (beloven)"} },
},

[8859] = { en = "Secrets of the Colossus - Zora", tier = 4,
  t = "Geheimen van de Colossus - Zora",
  d = "Mijn dienaren werden bijna gedood toen ze dit monster probeerden te bemachtigen. Je moet je echt haasten! Lord Maxwell Tyrosus wacht vol ongeduld op een vers monster van het omhulsel. Hij gelooft dat de geheimen van deze Colossus ons kunnen helpen in de oorlog tegen de Scourge!$B$BWaarom ben je hier nog!? Naar Light's Hope! Ja, je wordt rijkelijk beloond voor je moeite...$b",
  o = "Breng de Colossus of Zora's Husk naar Lord Maxwell Tyrosus in Light's Hope Chapel in de Eastern Plaguelands.$b",
  p = "Je lijkt een beetje zwaar te lopen, vriend.",
  c = "Uitstekend, en precies op tijd! Goed gedaan, $gjongen:meid;.",
  g = { {"dienaren", "servants (dienaar)"}, {"bemachtigen", "to obtain, to secure"}, {"haasten", "to hurry (zich haasten)"}, {"vol ongeduld", "eagerly, impatiently"}, {"monster", "sample"}, {"omhulsel", "husk, shell"}, {"rijkelijk", "handsomely, richly"}, {"beloond", "rewarded (belonen)"}, {"moeite", "effort, trouble"} },
},

[9248] = { en = "A Humble Offering", tier = 4,
  t = "Een bescheiden offer",
  d = "Ishnu-alah, $r. Laat me het bewijs zien dat een Lord of the Abyssal Council is gedood, dan beloon ik je met een voorwerp dat je zal helpen in je gevechten tegen de Qiraji.",
  o = "Aurel Goldleaf in Cenarion Hold in Silithus wil dat je haar 1 Abyssal Scepter brengt. Je moet ook Honored zijn bij de Cenarion Circle.",
  p = "Fandu-dath-belore? O, neem me niet kwalijk, $N. Ik herkende je niet. Heb je de scepter?$b",
  c = "Ande'thoras-ethil. Het betekent 'Mogen je zorgen kleiner worden' in mijn moedertaal.$B$BDraag de ring met trots en in goede gezondheid, $N.",
  g = { {"bescheiden", "humble, modest"}, {"offer", "offering"}, {"bewijs", "proof"}, {"gedood", "killed (doden)"}, {"beloon", "reward (belonen)"}, {"voorwerp", "object, item"}, {"neem me niet kwalijk", "pardon me"}, {"herkende", "recognized (herkennen)"}, {"mogen", "may (wish)"}, {"moedertaal", "native tongue"}, {"met trots", "proudly"} },
},

[9338] = { en = "Allegiance to Cenarion Circle", tier = 4,
  t = "Trouw aan de Cenarion Circle",
  p = "Ook als je de materiële beloningen die we aanbieden niet nodig hebt, staan deze insignes nog steeds voor ons wederzijds vertrouwen en onze vriendschap.$B$BBreng ze naar mij.  Ik zal je dienst goed noteren als je meer doet dan je plicht.",
  c = "Je eert ons, $N. Met je blijvende inzet zullen we alle obstakels overwinnen.",
  g = { {"trouw", "allegiance, loyalty"}, {"materiële", "material (materieel)"}, {"beloningen", "rewards (beloning)"}, {"insignes", "badges (insigne)"}, {"staan voor", "stand for, mark"}, {"wederzijds", "mutual"}, {"dienst", "service"}, {"noteren", "to note down"}, {"plicht", "duty"}, {"eert", "honor (eren)"}, {"inzet", "effort, commitment"}, {"obstakels", "obstacles (obstakel)"}, {"overwinnen", "to overcome"} },
},

[9415] = { en = "Report to Marshal Bluewall", tier = 4,
  t = "Meld je bij Marshal Bluewall",
  d = "Zijn jullie de nieuwe rekruten van Marshal Bluewall? Natuurlijk zijn jullie dat.$b$bWaar wachten jullie op? Goede soldaten sterven in de woestijn. Hebben jullie geen zin om je bij hen aan te sluiten?$b$bVooruit, op weg, en droog onderweg niet uit.",
  o = "Spreek met Marshal Bluewall in het kamp van de Alliance bij Hive'Zora.",
  c = "De Alliance heeft iedereen nodig die kan vechten. De Horde krijgt een gestage stroom versterkingen uit het noorden van het continent, en het is moeilijk om bij te blijven.$B$BIk zal je uitleggen hoe het ervoor staat.",
  g = { {"meld je", "report (zich melden)"}, {"rekruten", "recruits (rekruut)"}, {"sterven", "to die"}, {"aan te sluiten", "to join (zich aansluiten)"}, {"droog niet uit", "don't dry out (uitdrogen)"}, {"gestage", "steady (gestaag)"}, {"versterkingen", "reinforcements (versterking)"}, {"bij te blijven", "to keep up (bijblijven)"}, {"hoe het ervoor staat", "what the situation is"} },
},

[9419] = { en = "Scouring the Desert", tier = 4,
  t = "De woestijn uitkammen",
  d = "We ontdekten onlangs dat de Horde de woestijn van Silithus afzoekt naar grondstoffen, maar we schonken er weinig aandacht aan. We dachten dat het de moeite niet waard was om grote aantallen in deze snikhete woestijn te stationeren.$b$bMaar toen werd ontdekt hoe belangrijk de grondstoffen zijn, en nu moeten we haastig een achterstand inhalen.$b$bAls ik op je hulp kan rekenen, moet je de woestijn in gaan, de silithyst terughalen en die hier brengen.",
  o = "Vind Silithyst en lever het af bij de Silithyst Extractor, en spreek daarna met Marshal Bluewall in het kamp van de Alliance bij Hive'Zora.",
  p = "Wees voorzichtig daarbuiten, maar ook snel. We hebben geen tijd te verliezen.",
  c = "Het Licht zij dank, het is je gelukt.$B$BHadden we hier maar eerder mee kunnen beginnen, dan was onze nood nu niet zo groot. We moeten voorkomen dat de rijkdom van de woestijn in handen van de Horde valt.",
  o1 = "Lever Silithyst in",
  g = { {"uitkammen", "to scour, to comb"}, {"afzoekt", "searches (afzoeken)"}, {"grondstoffen", "resources, raw materials (grondstof)"}, {"schonken er weinig aandacht aan", "paid little mind to it (aandacht schenken)"}, {"de moeite niet waard", "not worth it"}, {"snikhete", "sweltering (snikheet)"}, {"stationeren", "to station"}, {"haastig", "hastily"}, {"een achterstand inhalen", "to catch up"}, {"rekenen op", "to count on"}, {"Het Licht zij dank", "Thank the Light"}, {"nood", "need, distress"}, {"voorkomen", "to prevent"}, {"rijkdom", "wealth, bounty"} },
},

})

